42	/// No device/simulator/CI exists yet to run a true platform-channel
43	/// integration test (AGENTS.md's "Running and verifying" TODO), so the
44	/// native secure-storage channel is faked with an in-memory store here —
45	/// the test still exercises the *real* `FlutterSecureStorage` instance
46	/// resolved from the single DI container, round-tripping a write/read
47	/// through it exactly as AC4 requires.
48	void main() {
49	  TestWidgetsFlutterBinding.ensureInitialized();
50	
51	  const secureStorageChannel = MethodChannel(
52	    'plugins.it_nomads.com/flutter_secure_storage',
53	  );
54	  final fakeNativeStorage = <String, String>{};
55	
56	  Future<dynamic> handleSecureStorageCall(MethodCall call) async {
57	    final args = call.arguments as Map<dynamic, dynamic>;
58	    switch (call.method) {
59	      case 'write':
60	        fakeNativeStorage[args['key'] as String] = args['value'] as String;
61	        return null;
62	      case 'read':
63	        return fakeNativeStorage[args['key'] as String];
64	      case 'delete':
65	        fakeNativeStorage.remove(args['key'] as String);
66	        return null;
67	      case 'containsKey':
68	        return fakeNativeStorage.containsKey(args['key'] as String);
69	      default:
70	        return null;
71	    }
72	  }
73	
74	  // Review finding: `record_pkg.AudioRecorder`'s constructor itself (not
75	  // just a later method call) immediately invokes this native channel —
76	  // `registerLazySingleton<record_pkg.AudioRecorder>(AudioRecorder.new)`
77	  // in `capture_injection.dart` throws `MissingPluginException` under
78	  // `flutter test` without this, same rationale as the secure-storage
79	  // channel above (no device/simulator exists yet, AGENTS.md). Nothing
80	  // in this file's tests actually records audio, so every method just
81	  // returns `null`, mirroring the secure-storage fake's own `default`.
82	  const recordChannel = MethodChannel('com.llfbandit.record/messages');
83	
84	  // spec-6-3 — `ChatCubit`'s own constructor subscribes to
85	  // `ConnectivityWatcher.watch()` immediately, and `registerChatFeature()`
86	  // wires it to the real `connectivity_plus`-backed `ConnectivityPlusWatcher`
87	  // (`Connectivity()`); this test force-resolves the real `ChatCubit` below
88	  // (`sl<ChatCubit>()`), which would otherwise hit these two platform
