15	Entry _entry(String id) => Entry(
16	  id: id,
17	  content: 'content-$id',
18	  source: EntrySource.manual,
19	  chatMessageId: null,
20	  occurredAt: '2026-01-01T00:00:00Z',
21	  serverRevision: 1,
22	  createdAt: '2026-01-01T00:00:00Z',
23	  updatedAt: '2026-01-01T00:00:00Z',
24	);
25	
26	/// A plain (non-mocktail) fake — same convention
27	/// `entries_search_cubit_test.dart`'s own `_FakeEntriesRepository` fake
28	/// uses: several tests here need to resolve two calls out of order (the
29	/// stale-in-flight-call generation guard), which a single static mocktail
30	/// stub can't express as naturally.
31	class _FakeDashboardRepository implements DashboardRepository {
32	  final List<Either<Failure, DashboardAggregate>> _results = [];
33	  final List<Completer<Either<Failure, DashboardAggregate>>> _completers = [];
34	  final List<String> calls = [];
35	
36	  /// When `true`, [getAggregate] returns a `Completer`-backed future the
37	  /// test resolves explicitly (via [resolve]) rather than immediately
38	  /// returning a queued result.
39	  bool gated = false;
40	
41	  void queue(Either<Failure, DashboardAggregate> result) {
42	    _results.add(result);
43	  }
44	
45	  void resolve(int callIndex, Either<Failure, DashboardAggregate> result) {
46	    _completers[callIndex].complete(result);
47	  }
48	
49	  @override
50	  Future<Either<Failure, DashboardAggregate>> getAggregate({
51	    required String period,
52	  }) {
53	    calls.add(period);
54	    if (gated) {
55	      final completer = Completer<Either<Failure, DashboardAggregate>>();
56	      _completers.add(completer);
57	      return completer.future;
58	    }
59	    if (_results.isEmpty) {
60	      throw StateError(
61	        'no queued getAggregate() result for call #${calls.length}',
62	      );
63	    }
64	    return Future.value(_results.removeAt(0));
65	  }
66	}
67	
68	/// A plain (non-mocktail) fake [PendingEntryWriteTracker] — [emitConfirmed]
69	/// lets a test drive the Boundaries' own "recomputing on each event"
70	/// requirement directly, without any capture cubit actually in play.
71	class _FakePendingEntryWriteTracker implements PendingEntryWriteTracker {
72	  final _confirmedController =
73	      StreamController<({String tempId, Entry entry})>.broadcast();
74	
75	  void emitConfirmed() {
76	    _confirmedController.add((tempId: 'temp-1', entry: _entry('e1')));
77	  }
78	
79	  @override
80	  Future<Either<Failure, Entry>> create({
81	    required String content,
82	    required EntrySource source,
83	    int? mediaDurationSeconds,
84	  }) async => throw UnimplementedError('not expected to be called');
85	
86	  @override
87	  Future<void> retry(String tempId) async =>
88	      throw UnimplementedError('not expected to be called');
89	
90	  @override
91	  Stream<List<PendingEntryWrite>> get pendingWrites => const Stream.empty();
92	
93	  @override
94	  Stream<({String tempId, Entry entry})> get confirmedWrites =>
95	      _confirmedController.stream;
96	
97	  @override
98	  Future<void> dispose() => _confirmedController.close();
99	}
100	
101	/// Collects every state the cubit emits for the duration of [act] — same
102	/// helper `entries_search_cubit_test.dart` already documents.
103	Future<List<Resource<DashboardAggregate>>> _emittedDuring(
104	  DashboardCubit cubit,
105	  FutureOr<void> Function() act,
106	) async {
107	  final emitted = <Resource<DashboardAggregate>>[];
108	  final subscription = cubit.stream.listen(emitted.add);
109	  await act();
110	  // Flushes any state the broadcast `StreamController` has already queued
111	  // for delivery but not yet dispatched to this listener (`Cubit.emit`'s
112	  // underlying controller is not `sync`) — without this, a `load()` whose
113	  // own awaited repository call resolves synchronously can have its final
114	  // `emit()` still pending delivery at the exact microtask `act()`'s
115	  // returned Future completes on.
116	  await Future<void>.delayed(Duration.zero);
117	  await subscription.cancel();
118	  return emitted;
119	}
120	
121	void main() {
122	  late _FakeDashboardRepository fakeRepository;
123	  late _FakePendingEntryWriteTracker fakeTracker;
124	  late DashboardCubit cubit;
125	
126	  setUp(() {
127	    fakeRepository = _FakeDashboardRepository();
128	    fakeTracker = _FakePendingEntryWriteTracker();
129	    cubit = DashboardCubit(fakeRepository, fakeTracker);
130	  });
131	
132	  tearDown(() async {
133	    if (!cubit.isClosed) {
134	      await cubit.close();
135	    }
136	    await fakeTracker.dispose();
137	  });
138	
139	  test('starts as ResourceIdle', () {
140	    expect(cubit.state, const ResourceIdle<DashboardAggregate>());
