/// `dashboard_remote_data_source_test.dart`'s own fixture; the domain layer
/// never reads these, but the DTO's `@JsonSerializable` requires all four.
Map<String, dynamic> _sourcesJson() => {
  'manual': 0,
  'audio': 0,
  'photo': 0,
  'chat': 0,
};

