  'date': date,
  'count': count,
  'sources': _sourcesJson(),
};

Map<String, dynamic> _aggregateJson({
  required int totalCount,
  required List<Map<String, dynamic>> buckets,
}) => {
  'data': {
    'buckets': buckets,
    'totals': {'count': totalCount, 'sources': _sourcesJson()},
  },
};

